const failure = $input.first().json;
const info = {
  workflow: failure.workflow?.name || 'Unknown workflow',
  executionId: failure.execution?.id || 'unknown',
  failedNode: failure.execution?.lastNodeExecuted || 'unknown',
  error: String(failure.execution?.error?.message || failure.trigger?.error?.message || 'Unknown failure').slice(0, 240),
  observedAt: new Date().toISOString(),
};
console.error('[LendLoop workflow failure]', JSON.stringify(info));
// Replace this logger with an incident channel or monitored alert destination in production.
return [{ json: info }];
